5|protocol ArchiveDocumentLoading: Actor {
6|    func open(url: URL) async throws -> ArchiveDocumentSnapshot
7|    func materializePreview(entryID: ArchiveEntryID) async throws -> URL
8|}
9|
10|actor ArchiveDocumentLoader: ArchiveDocumentLoading {
11|    private let provider: ZIPArchiveProvider
12|    private var previewSessionURL: URL?
13|    private var activePreviewRootURL: URL?
14|
15|    init(provider: ZIPArchiveProvider = ZIPArchiveProvider()) {
16|        self.provider = provider
17|    }
18|
19|    deinit {
20|        if let previewSessionURL {
21|            try? FileManager.default.removeItem(at: previewSessionURL)
22|        }
23|    }
24|
25|    func open(url: URL) async throws -> ArchiveDocumentSnapshot {
26|        try resetPreviewSession()
27|        let accessed = url.startAccessingSecurityScopedResource()
28|        defer {
29|            if accessed { url.stopAccessingSecurityScopedResource() }
30|        }
31|        return try await provider.open(url: url)
32|    }
33|
34|    func materializePreview(entryID: ArchiveEntryID) async throws -> URL {
35|        try Task.checkCancellation()
36|        guard let previewSessionURL else { throw ArchiveError.helperFailed }
37|        let requestRoot = previewSessionURL.appending(
38|            path: UUID().uuidString,
39|            directoryHint: .isDirectory
40|        )
41|        try FileManager.default.createDirectory(
42|            at: requestRoot,
43|            withIntermediateDirectories: false,
44|            attributes: [.posixPermissions: 0o700]
45|        )
46|        activePreviewRootURL = requestRoot
47|        do {
48|            try Task.checkCancellation()
49|            let materializedURL = try await provider.materializeEntry(id: entryID, under: requestRoot)
50|            try Task.checkCancellation()
51|            if let activePreviewRootURL, activePreviewRootURL != requestRoot {
52|                try? FileManager.default.removeItem(at: activePreviewRootURL)
53|            }
54|            activePreviewRootURL = requestRoot
55|            return materializedURL
56|        } catch {
57|            try? FileManager.default.removeItem(at: requestRoot)
58|            if activePreviewRootURL == requestRoot {
59|                activePreviewRootURL = nil
60|            }
61|            throw error
62|        }
63|    }
64|
65|    private func resetPreviewSession() throws {
66|        let root = ValidatedPreviewCacheURL.cacheRoot
67|        if let previewSessionURL {
68|            try? FileManager.default.removeItem(at: previewSessionURL)
69|        }
70|        try FileManager.default.createDirectory(
71|            at: root,
72|            withIntermediateDirectories: true,
73|            attributes: [.posixPermissions: 0o700]
74|        )
75|        try? FileManager.default.setAttributes([.posixPermissions: 0o700], ofItemAtPath: root.path)
76|        let session = root.appending(path: UUID().uuidString, directoryHint: .isDirectory)
77|        try FileManager.default.createDirectory(
78|            at: session,
79|            withIntermediateDirectories: false,
80|            attributes: [.posixPermissions: 0o700]
81|        )
82|        previewSessionURL = session
83|        activePreviewRootURL = nil
84|    }
