26|struct PreviewRoutingPolicy: Sendable {
27|    func kind(forFilename filename: String) -> PreviewKind {
28|        let fileExtension = URL(fileURLWithPath: filename).pathExtension.lowercased()
29|        switch fileExtension {
30|        case "png", "jpg", "jpeg", "heic", "gif", "tif", "tiff", "bmp", "webp", "svg":
31|            return .image
32|        case "mp4", "mov", "m4v":
