48|struct ValidatedPreviewCacheURL: Equatable, Sendable {
49|    let url: URL
50|    private let relativeComponents: [String]
51|
52|    static let maximumPreviewBytes = 256 * 1_024 * 1_024
53|
54|    static var cacheRoot: URL {
55|        FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0]
56|            .appendingPathComponent("ArchiveWorkbench/PreviewCache", isDirectory: true)
57|    }
58|
59|    init?(candidateURL: URL) {
60|        guard let components = Self.relativeComponents(for: candidateURL),
61|              let descriptor = Self.openValidatedFile(
62|                relativeComponents: components,
63|                maximumBytes: Self.maximumPreviewBytes
64|              ) else { return nil }
65|        close(descriptor)
66|
67|        var securedURL = Self.cacheRoot.standardizedFileURL
68|        for component in components {
69|            securedURL.appendPathComponent(component)
70|        }
71|        url = securedURL
72|        relativeComponents = components
73|    }
74|
75|    func readData(
76|        maximumBytes: Int = Self.maximumPreviewBytes,
77|        beforeOpeningFinalComponent: (() -> Void)? = nil
78|    ) -> Data? {
79|        guard maximumBytes >= 0,
80|              maximumBytes < Int.max,
81|              let descriptor = Self.openValidatedFile(
82|                relativeComponents: relativeComponents,
83|                maximumBytes: maximumBytes,
84|                beforeOpeningFinalComponent: beforeOpeningFinalComponent
85|              ) else { return nil }
86|
87|        let handle = FileHandle(fileDescriptor: descriptor, closeOnDealloc: true)
88|        let readLimit = maximumBytes + 1
89|        var result = Data()
90|        do {
91|            while result.count < readLimit {
92|                guard !Task.isCancelled else { return nil }
93|                let requestedBytes = min(64 * 1_024, readLimit - result.count)
94|                guard let chunk = try handle.read(upToCount: requestedBytes),
95|                      !chunk.isEmpty else {
96|                    return result
97|                }
98|                result.append(chunk)
99|            }
100|        } catch {
101|            return nil
102|        }
103|        return result
104|    }
105|
106|    private static func relativeComponents(for candidateURL: URL) -> [String]? {
107|        let root = cacheRoot.standardizedFileURL
108|        let candidatePath = candidateURL.path
109|        guard candidateURL.isFileURL,
110|              candidatePath.hasPrefix(root.path + "/") else { return nil }
111|        let relativePath = candidatePath.dropFirst(root.path.count + 1)
112|        let components = relativePath.split(separator: "/", omittingEmptySubsequences: false).map(String.init)
113|        guard !components.isEmpty,
114|              components.allSatisfy({ !$0.isEmpty && $0 != "." && $0 != ".." }) else {
115|            return nil
116|        }
117|        return components
118|    }
119|
120|    private static func openValidatedFile(
121|        relativeComponents: [String],
122|        maximumBytes: Int,
123|        beforeOpeningFinalComponent: (() -> Void)? = nil
124|    ) -> Int32? {
125|        guard maximumBytes >= 0,
126|              !relativeComponents.isEmpty,
127|              relativeComponents.allSatisfy({ !$0.isEmpty && $0 != "." && $0 != ".." }) else {
128|            return nil
129|        }
130|
131|        var currentDescriptor = open(
132|            cacheRoot.path,
133|            O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC
134|        )
135|        guard currentDescriptor >= 0,
136|              descriptor(currentDescriptor, hasType: S_IFDIR) else {
137|            if currentDescriptor >= 0 { close(currentDescriptor) }
138|            return nil
139|        }
140|        defer { close(currentDescriptor) }
141|
142|        for component in relativeComponents.dropLast() {
143|            let nextDescriptor = openat(
144|                currentDescriptor,
145|                component,
146|                O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC
147|            )
148|            guard nextDescriptor >= 0,
149|                  descriptor(nextDescriptor, hasType: S_IFDIR) else {
150|                if nextDescriptor >= 0 { close(nextDescriptor) }
151|                return nil
152|            }
153|            close(currentDescriptor)
154|            currentDescriptor = nextDescriptor
155|        }
156|
157|        beforeOpeningFinalComponent?()
158|        guard let finalComponent = relativeComponents.last else { return nil }
159|        let fileDescriptor = openat(
160|            currentDescriptor,
161|            finalComponent,
162|            O_RDONLY | O_NOFOLLOW | O_CLOEXEC
163|        )
164|        guard fileDescriptor >= 0 else { return nil }
165|
166|        var fileStatus = stat()
167|        guard fstat(fileDescriptor, &fileStatus) == 0,
168|              fileStatus.st_mode & S_IFMT == S_IFREG,
169|              fileStatus.st_size >= 0,
170|              fileStatus.st_size <= off_t(maximumBytes) else {
171|            close(fileDescriptor)
172|            return nil
173|        }
174|        return fileDescriptor
175|    }
176|
177|    private static func descriptor(_ descriptor: Int32, hasType type: mode_t) -> Bool {
178|        var descriptorStatus = stat()
179|        return fstat(descriptor, &descriptorStatus) == 0
180|            && descriptorStatus.st_mode & S_IFMT == type
181|    }
